// Each palette: the base's extra-dark shade, a seven-shade ramp for the
// bands (lightest first, matching FRIEND10_LAYERS order), and the glow
// colour the aura uses — a mid tone of the same hue, because a friend's
// glow IS its body colour (design-bible §3). The three hues are the
// same reward-stream pastels every archetype wears, extended
// one step lighter and one darker to cover this trace's wider range.
export const FRIEND10_GREYS = {
  base: '#333333',
  ramp: [
    '#d0d0d0',
    '#b9b9b9',
    '#a3a3a3',
    '#8c8c8c',
    '#767676',
    '#606060',
    '#494949',
  ],
  glow: '#8c8c8c',
}

export const FRIEND10_PALETTES = {
  green: {
    base: '#113f28',
    ramp: [
      '#b2ecd2',
      '#8fe3bb',
      '#6cdaa5',
      '#47d18f',
      '#2fbd79',
      '#269a62',
      '#1d754b',
    ],
    glow: '#2fbd79',
  },
  violet: {
    base: '#231250',
    ramp: [
      '#c0aeee',
      '#a68fe3',
      '#8a6cda',
      '#6c47d1',
      '#562fbd',
      '#46269a',
      '#351d75',
    ],
    glow: '#562fbd',
  },
  amber: {
    base: '#4f3a11',
    ramp: [
      '#ecd9b2',
      '#e3c78f',
      '#dab66c',
      '#d1a447',
      '#bd8e2f',
      '#9a7426',
      '#75581d',
    ],
    glow: '#bd8e2f',
  },
}

// Where Kimia's two traced eye placeholders sat: centres and radii
// measured from the source's placeholder ellipses, already shifted into
// viewBox space (the placeholders lived in the trace's offset space).
export const FRIEND10_EYES = [
  { cx: 162.7, cy: 511.5, r: 8.0 },
  { cx: 344.5, cy: 519.5, r: 8.4 },
]

const glowId = (prefix) => `${prefix}friend10-glow`

/* WHY THE BODY AND EYES ARE SEPARATE COMPONENTS (2026-07-26, and the
 * reference every friendNN.jsx points at since 2026-08-17, when the
 * pilot drawing that first carried this note was retired): when anything
 * animates INSIDE an <svg>, the browser re-rasterises that svg's whole
 * content — and a friend body is several enormous traced paths plus a
 * Gaussian-blur aura, expensive to redraw. With the blinking eyes in the
 * same svg, every blink would re-blur the entire figure on every
 * animation frame of the squash: a jank spike on modest hardware,
 * repeating each cycle. So every assembled friend ships as TWO stacked
 * SVGs — a heavy static body, painted once, and a featherweight overlay
 * of blinking eyes laid exactly over it, sharing the same viewBox so the
 * eyes land where Kimia drew them. Keep this split wherever a friend is
 * drawn.
 */

// Defs for the BODY svg: just the aura's blur filter. (This canvas is
// ~2.7× the retired pilot's, so the blur radius scales up to match.)
export function Friend10BodyDefs({ prefix = '' }) {
  return (
    <filter id={glowId(prefix)} x="-40%" y="-40%" width="180%" height="180%">
      <feGaussianBlur stdDeviation="14" />
    </filter>
  )
}

// The heavy, static half: glow aura (the sealed silhouette blurred and
// filled the body colour) → the reconstructed dark base → the seven
// bands. No animation may ever live in this svg (see friend10.jsx).
export function Friend10Body({ palette = FRIEND10_GREYS, prefix = '' }) {
  return (
    <g transform={FRIEND10_OFFSET}>
      <path
        d={FRIEND10_BASE}
        fill={palette.glow}
        opacity="0.8"
        filter={`url(#${glowId(prefix)})`}
      />
      <path d={FRIEND10_BASE} fill={palette.base} />
      {FRIEND10_LAYERS.map((d, i) => (
        <path
          key={i}
          d={d}
          fill={palette.ramp[i] ?? palette.ramp[palette.ramp.length - 1]}
        />
      ))}
    </g>
  )
}

// The light, animated half: the two canonical yellow eyes, each in its
// own .friend-eye-blink wrapper (index.css). Render inside an <svg>
// with the friend-10 viewBox and one <EyeDefs prefix/> in its defs.
export function Friend10Eyes({ prefix = '' }) {
  return (
    <g>
      {FRIEND10_EYES.map((eye, i) => (
        <g key={i} className="friend-eye-blink">
          <Eye cx={eye.cx} cy={eye.cy} r={eye.r} prefix={prefix} />
        </g>
      ))}
    </g>
  )
}
